#!/usr/bin/env python3
"""Generate FireOpsSim skill-support catalog JSON. Source of truth after generation: data/skill-support/*.json"""
from __future__ import annotations

import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from skill_support_lib import SHARED_SOURCES, drill, mode, q, res, skill, src  # noqa: E402

ROOT = Path(__file__).resolve().parents[1] / "data" / "skill-support"


def dump(name, payload):
    ROOT.mkdir(parents=True, exist_ok=True)
    path = ROOT / name
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {path.relative_to(ROOT.parent.parent)} ({len(payload.get('skills', payload.get('catalogFiles', [])))} items)")


