        {"id": "officer", "label": "Company Officer", "blurb": "Fire Officer I", "certIds": ["fire_officer_1"]},
        {"id": "instructor", "label": "Instructor", "blurb": "Fire Instructor I", "certIds": ["fire_instructor_1"]},
