def dump_handoff(certs):
    skills = []
    for cert in certs:
        for item in cert.get("skills") or []:
            skills.append({
                "certificationId": cert["id"],
                "certificationTitle": cert.get("shortTitle") or cert.get("title"),
                "skillId": item["id"],
                "title": item["title"],
                "url": f"/skill-support.html?cert={cert['id']}&task={item['id']}",
            })
    dump("handoff.json", {
        "schemaVersion": 1,
        "updatedAt": "2026-08-28",
        "purpose": "Stable FireOpsSim Skill Support URLs for FireOps Career Road Taskbook and Daily Focus handoffs. Completing a session never marks a Roadmap task complete.",
        "sessionPage": "/skill-support.html",
        "dailyFocus": {
            "currentRoadmapUrl": "/focus-drills.html",
            "behavior": "When source=roadmap, FireOpsSim redirects Daily Focus links to Skill Support. Skill Support accepts task, task_id, cert, certification, qualification, level, requirement, requirement_id, topic/title, goal, state, and return_url.",
            "levelToCert": {
                "probationary": "probationary_firefighter",
                "firefighter_1": "firefighter_1",
                "firefighter_2": "firefighter_2",
                "hazmat_ops": "hazmat_operations",
                "driver_operator": "driver_operator_pumper",
                "officer_1": "fire_officer_1",
                "instructor_1": "fire_instructor_1",
            },
        },
        "skills": skills,
    })


def main():
    from skill_packs_ff import cert_ff1
    from skill_packs_ops import cert_ff2, cert_hazmat
    from skill_packs_lead import cert_fo1, cert_fi1, cert_probation

    certs = [
        cert_probation(),
        cert_ff1(),
        cert_ff2(),
        cert_hazmat(),
        cert_do_pumper(),
        cert_fo1(),
        cert_fi1(),
    ]
    dump("index.json", build_index(certs))
    dump_handoff(certs)
    for cert in certs:
        dump(f"{cert['id']}.json", cert)
    n = sum(len(c["skills"]) for c in certs)
    print(f"total skills: {n}")


if __name__ == "__main__":
    main()

